const distanciaKm = ([latitudeA, longitudeA], [latitudeB, longitudeB]) => {
  const toRadians = (value) => value * Math.PI / 180;
  const latitudeDistance = toRadians(latitudeB - latitudeA);
  const longitudeDistance = toRadians(longitudeB - longitudeA);
  const originLatitude = toRadians(latitudeA);
  const destinationLatitude = toRadians(latitudeB);
  const arc = Math.sin(latitudeDistance / 2) ** 2 + Math.cos(originLatitude) * Math.cos(destinationLatitude) * Math.sin(longitudeDistance / 2) ** 2;
  return 6371 * 2 * Math.atan2(Math.sqrt(arc), Math.sqrt(1 - arc));
};
const Icono = ({ icon, size = 20, className = "" }) => <MorphIcon icon={icon} size={size} strokeWidth={2} className={className} />;

function SelectorMapa({ onPick }) { useMapEvents({ click: (event) => onPick([event.latlng.lat, event.latlng.lng]) }); return null; }
function MapaSanLuis({ salones, salonSeleccionadoId, onSalonSelect, ubicacionBorrador, onSeleccionarUbicacion, ubicacionUsuario, interactive = false }) {
  return <MapContainer className="slrc-map" center={centroSlrc} zoom={13} minZoom={12} maxZoom={17} maxBounds={limitesSlrc} maxBoundsViscosity={1} scrollWheelZoom={false}><TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />{salones.map((salon) => <CircleMarker key={salon.id} center={salon.ubicacion} radius={salon.id === salonSeleccionadoId ? 11 : 8} pathOptions={{ color: "#10213B", fillColor: salon.id === salonSeleccionadoId ? "#D8E89B" : "#FFB870", fillOpacity: 1, weight: 2 }} eventHandlers={{ click: () => onSalonSelect?.(salon.id) }}><Popup><strong>{salon.nombre}</strong><br />{salon.tipo} · {salon.capacidad} personas<br /><a href={`tel:${salon.telefono.replace(/\s/g, "")}`}>{salon.telefono}</a></Popup></CircleMarker>)}{ubicacionUsuario && <CircleMarker center={ubicacionUsuario} radius={9} pathOptions={{ color: "#FFFFFF", fillColor: "#2E8BC0", fillOpacity: 1, weight: 3 }}><Popup>Tu ubicación</Popup></CircleMarker>}{ubicacionBorrador && <CircleMarker center={ubicacionBorrador} radius={10} pathOptions={{ color: "#10213B", fillColor: "#FFFFFF", fillOpacity: 1, weight: 3 }} />}{interactive && <SelectorMapa onPick={onSeleccionarUbicacion} />}</MapContainer>;
}
function CajaChat({ salon, mensajes, setMensajes, alIniciarVideo }) {
  const [mensaje, setMensaje] = useState("");
  const enviarMensaje = (event) => { event.preventDefault(); if (!mensaje.trim()) return; setMensajes((current) => [...current, { id: Date.now(), from: "Tú", text: mensaje.trim() }]); setMensaje(""); };
  return <section className="chat-box" aria-label={`Chat con ${salon.nombre}`}><div className="chat-head"><div><span>CONVERSACIÓN DEMO</span><h3>{salon.nombre}</h3></div><a href={`tel:${salon.telefono.replace(/\s/g, "")}`} className="icon-button" aria-label={`Llamar a ${salon.nombre}`}><Icono icon={Phone} size={18} /></a><button className="icon-button" onClick={alIniciarVideo} aria-label="Iniciar videollamada"><Icono icon={Video} size={18} /></button></div><div className="chat-messages">{mensajes.map((item) => <p key={item.id} className={item.from === "Tú" ? "mine" : "theirs"}><b>{item.from}</b>{item.text}</p>)}</div><form className="chat-compose" onSubmit={enviarMensaje}><label className="sr-only" htmlFor="chat-mensaje">Mensaje</label><input id="chat-mensaje" value={mensaje} onChange={(event) => setMensaje(event.target.value)} placeholder="Escribe al dueño..." /><button type="submit" aria-label="Enviar mensaje"><Icono icon={Send} size={17} /></button></form></section>;
}

